//	      "uploadRequestSupported": true,
//	      "objectRegistrationSupported": true,
//	      "supportedUploadMethodTypes": ["s3", "https", "gs"],
//	      "maxUploadSize": 5368709120,
//	      "maxUploadRequestLength": 50,
//	      "validateChecksums": true,
//	      "validateFileSizes": false,
